function normalizeState(raw){const base=structuredClone(DEFAULT);if(!raw||typeof raw!=="object")return base;const out={...base,...raw};for(const k of ["orders","auction","ownedCars","ledger","history"]){if(!Array.isArray(raw[k]))out[k]=base[k]}out.checked=raw.checked&&typeof raw.checked==="object"?raw.checked:{};out.findings=raw.findings&&typeof raw.findings==="object"?raw.findings:{};out.approvals=raw.approvals&&typeof raw.approvals==="object"?raw.approvals:{};out.completed=raw.completed&&typeof raw.completed==="object"?raw.completed:{};out.findings=raw.findings&&typeof raw.findings==="object"?raw.findings:{};out.approvals=raw.approvals&&typeof raw.approvals==="object"?raw.approvals:{};out.inventory=raw.inventory&&typeof raw.inventory==="object"?raw.inventory:{};out.garage={...base.garage,...(raw.garage||{})};out.network=raw.network&&typeof raw.network==="object"?raw.network:structuredClone(base.network);out.network.branches=Array.isArray(out.network.branches)&&out.network.branches.length?out.network.branches:structuredClone(base.network.branches);out.repairedParts=raw.repairedParts&&typeof raw.repairedParts==="object"?raw.repairedParts:{};out.testDrives=raw.testDrives&&typeof raw.testDrives==="object"?raw.testDrives:{};out.vehicleHistory=raw.vehicleHistory&&typeof raw.vehicleHistory==="object"?raw.vehicleHistory:{};out.diagnostics=raw.diagnostics&&typeof raw.diagnostics==="object"?raw.diagnostics:{};out.repair=raw.repair&&typeof raw.repair==="object"?{step:0,part:null,taskType:"main",...raw.repair}:{step:0,part:null,taskType:"main"};out.premium=Math.max(0,Number(out.premium)||0);out.vipUntil=Math.max(0,Number(out.vipUntil)||0);if(!Array.isArray(raw.staff))out.staff=[];if(Number.isInteger(raw.staff)&&raw.staff>0)out.staff=Array.from({length:raw.staff},(_,i)=>({name:"Механик",salary:3500,bonus:0}));out.activeOrder=Math.max(0,Math.min(Number.isInteger(out.activeOrder)?out.activeOrder:0,Math.max(0,out.orders.length-1)));if(!SYSTEMS[out.zone])out.zone="engine";return out}
