function save(){localStorage.setItem(KEY,JSON.stringify(S));render()}function fmt(n){return Math.round(n).toLocaleString("ru-RU")}function addMoney(n){S.money+=n;S.ledger.unshift({day:S.day,value:n})}function addXP(n){S.xp+=n;while(S.xp>=S.level*100){S.xp-=S.level*100;S.level++;S.rep=Math.min(100,S.rep+2)}}function modal(h){document.getElementById("modalBody").innerHTML=h;document.getElementById("modal").classList.remove("hidden")}function closeModal(){document.getElementById("modal").classList.add("hidden")}function tab(t){document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));document.getElementById("tab-"+t).classList.add("active");const b=document.querySelector('.nav[data-tab="'+t+'"]');if(b)b.classList.add("active")}function activeOrder(){return S.orders[S.activeOrder]}function partWear(name,defaultWear){return Number.isFinite(S.repairedParts?.[name])?S.repairedParts[name]:defaultWear}function diagDiscount(){return S.garage.diagnostic>=2?.8:1}function warehouseCap(){return 8+S.garage.warehouse*4}function staffSalary(){return S.staff.reduce((a,x)=>a+x.salary,0)}function staffBonus(){return S.staff.reduce((a,x)=>a+x.bonus,0)}
function orderKey(){return String(S.activeOrder)}
function vehicleKey(o){return o?`${o.car}_${o.client}`:"unknown"}
function vehicleHistory(o){const k=vehicleKey(o);S.vehicleHistory=S.vehicleHistory||{};S.vehicleHistory[k]=S.vehicleHistory[k]||{visits:0,notes:[]};return S.vehicleHistory[k]}
function isVip(){return Number(S.vipUntil)>Date.now()}
function grantProduct(id){const p=PREMIUM_PRODUCTS[id];if(!p)return;S.premium+=p.stars;if(id==="pro")S.vipUntil=Math.max(Date.now(),S.vipUntil)+7*86400000;if(id==="vip")S.vipUntil=Math.max(Date.now(),S.vipUntil)+30*86400000;S.history.unshift(`Покупка: ${p.title} (+${p.stars} премиум)`);save();modal(`<h2>✅ Покупка зачислена</h2><p>${p.title}</p><div class="notice">Премиум: <b>${fmt(S.premium)}</b> 💎${isVip()?`<br>VIP активен до ${new Date(S.vipUntil).toLocaleDateString("ru-RU")}`:""}</div><button class="btn gold" onclick="closeModal()">Продолжить</button>`)}
function startPayment(id){const p=PREMIUM_PRODUCTS[id];if(!p)return;const bridge=window.vkBridge||window.VKBridge;if(bridge&&typeof bridge.send==="function"){try{bridge.send("VKWebAppShowOrderBox",{type:"item",item:id}).catch(()=>{});return}catch(e){}}modal(`<h2>💳 ${p.title}</h2><p>${p.desc}</p><div class="notice">Цена: <b>${p.price}</b><br>Премиум-валюта: <b>+${fmt(p.stars)} 💎</b></div><p class="muted">В браузерной версии включён тестовый режим. В VK Mini App эта кнопка передаст товар в VK Bridge.</p><button class="btn gold" onclick="grantProduct('${id}')">Тестовая покупка</button><button class="btn dark" onclick="closeModal()">Отмена</button>`)}
function spendPremium(cost,action){if(S.premium<cost)return alert("Не хватает премиум-валюты.");S.premium-=cost;action();save()}
function render(){document.getElementById("money").textContent=fmt(S.money);document.getElementById("level").textContent=S.level;document.getElementById("rep").textContent=S.rep;document.getElementById("day").textContent=S.day;document.getElementById("badge").textContent=S.orders.length;renderGarage();renderOrders();renderRepair();renderDiagnostics();renderAuction();renderParts();renderStaff();renderUpgrade();renderFinance();renderProfile();renderShop();renderNetwork()}
function renderGarage(){const o=activeOrder(),c=o?CARS[o.car]:null;document.getElementById("tab-garage").innerHTML=`<div class="hero"><div><h1>Гараж <span class="badge">${VERSION}</span></h1><div class="muted">Теперь ошибка в диагностике стоит денег, а ремонтить нужно именно найденную неисправность.</div></div><button class="btn gold" onclick="newDay()">Начать новый день</button></div><div class="two"><div class="card"><h2>${c?c[0]:"Свободный гараж"}</h2>${c?`<div class="vehicle"><img src="${c[2]}"><button class="hotspot hs-engine" title="Двигатель" onclick="selectZone('engine')">⚙</button><button class="hotspot hs-brakes" title="Тормоза" onclick="selectZone('brakes')">◉</button><button class="hotspot hs-susp" title="Подвеска" onclick="selectZone('suspension')">⌁</button><button class="hotspot hs-electric" title="Электрика" onclick="selectZone('electrical')">⚡</button><button class="hotspot hs-body" title="Кузов" onclick="selectZone('body')">▣</button></div>`:`<div class="notice">Нет активного заказа.</div>`}</div><div class="card">${o?`<span class="tag">${o.urgent?"СРОЧНО":"ЗАКАЗ"}</span><h2>Жалоба клиента</h2><div class="notice">«${o.symptom}»</div><div class="statrow"><span>Клиент</span><b>${o.client}</b></div><div class="statrow"><span>Оплата</span><b class="moneyPlus">${fmt(o.pay)} ₽</b></div><button class="btn gold" onclick="tab('repair')">Перейти к работе</button>`:""}<h2 style="margin-top:22px">Состояние мастерской</h2><div class="statrow"><span>Подъёмники</span><b>${S.garage.lift}/3</b></div><div class="statrow"><span>Сотрудники</span><b>${S.staff.length}</b></div><div class="statrow"><span>Репутация</span><b>${S.rep}/100</b></div><div class="statrow"><span>Бонус персонала</span><b>+${staffBonus()} ₽/заказ</b></div></div></div>`}
function renderOrders(){document.getElementById("tab-orders").innerHTML=`<div class="hero"><div><h1>Заказы клиентов</h1><div class="muted">Основная неисправность определяется диагностикой, а скрытые неисправности нужно отдельно согласовать с клиентом.</div></div></div><div class="grid">${S.orders.map((o,i)=>{const c=CARS[o.car];return `<div class="card"><span class="tag">${o.urgent?"СРОЧНО":c[1]}</span><h3>${c[0]}</h3><div class="carArt"><img src="${c[2]}"></div><div class="notice">${o.symptom}</div><div class="statrow"><span>Оплата</span><b>${fmt(o.pay)} ₽</b></div><button class="btn ${i===S.activeOrder?"gold":"dark"}" onclick="pickOrder(${i})">${i===S.activeOrder?"В работе":"Взять заказ"}</button></div>`}).join("")||`<div class="notice">Заказов пока нет. Начни новый день.</div>`}</div>`}
function pickOrder(i){if(!S.orders[i])return;S.activeOrder=i;S.zone=S.orders[i].system;S.repair={step:0,part:null};save();tab("repair")}function selectZone(z){if(!SYSTEMS[z])return;S.zone=z;save();tab("repair")}
function renderRepair(){const o=activeOrder();if(!o){document.getElementById("tab-repair").innerHTML="<div class='notice'>Нет заказов. Начни новый день.</div>";return}const z=SYSTEMS[S.zone],checked=S.checked[S.activeOrder+"_"+S.zone]||[],findings=S.findings[String(S.activeOrder)]||[];const extras=findings.map((f,i)=>{const a=S.approvals[S.activeOrder+"_"+i];return `<div class="finding ${a==="yes"?"approved":a==="no"?"declined":""}"><div><b>${f.title}</b><p>${f.desc}</p><small>Запчасть ${fmt(f.partCost)} ₽ + работа ${fmt(f.labor)} ₽ = <b>${fmt(f.partCost+f.labor)} ₽</b></small></div><div>${a==="yes"?`<span class="tag greenTag">СОГЛАСОВАНО</span>`:a==="no"?`<span class="tag">ОТКАЗ</span>`:`<button class="btn gold" onclick="offerFinding(${i})">Предложить клиенту</button>`}</div></div>`}).join("");document.getElementById("tab-repair").innerHTML=`<div class="hero"><div><h1>Диагностика: ${CARS[o.car][0]}</h1><div class="muted">${o.service?"При обслуживании обязательно осматривай автомобиль: скрытые неисправности можно предложить клиенту отдельным ремонтом.":"Дополнительные неисправности появляются только после соответствующей проверки и требуют согласования клиента."}</div></div><span class="tag">${z.name}</span></div><div class="two"><div class="card"><div class="vehicle"><img src="${z.img}"></div><div class="zoneList" style="margin-top:9px">${Object.keys(SYSTEMS).map(k=>`<button class="zoneBtn ${k===S.zone?"active":""}" onclick="selectZone('${k}')">${SYSTEMS[k].name}</button>`).join("")}</div></div><div class="card"><h2>Диагностика</h2><div class="notice"><b>Задача клиента:</b> ${o.symptom}</div>${TESTS[S.zone].map((t,i)=>{const targets=TEST_TARGETS[S.zone]?.[i]||[];const mainHit=S.zone===o.system&&targets.includes(o.target);const extraHit=S.zone===o.system&&(o.extra||[]).some(f=>f.needTest===i&&targets.includes(f.part));return `<div class="test" onclick="runTest(${i})"><b>${t[0]} ${checked.includes(i)?"✓":""}</b><small>${t[2]} • ${fmt(Math.round(t[1]*diagDiscount()))} ₽${mainHit?" • основная неисправность":""}${extraHit?" • возможна доп. находка":""}</small></div>`}).join("")}<div class="muted">Неверные проверки не дают ответ, но деньги списываются.</div></div></div><div class="card" style="margin-top:14px"><h2>🚗 Тест-драйв и выдача</h2><div class="notice">После основной работы и всех согласованных дополнительных ремонтов проведи тест-драйв. Только после успешной проверки заказ можно закрыть.</div><button class="btn green" onclick="testDrive()" ${S.testDrives[S.activeOrder]?"disabled":""}>${S.testDrives[S.activeOrder]?"Тест-драйв пройден":"Провести тест-драйв"}</button></div>${extras?`<div class="card findingBox"><h2>🔎 Дополнительные неисправности</h2>${extras}</div>`:""}<div class="card" style="margin-top:14px"><h2>Детали узла</h2><div class="partsGrid">${z.parts.map((p,i)=>{const wear=partWear(p[0],p[2]),isTarget=o.target===p[0]&&S.diagnostics?.[String(S.activeOrder)]?.confirmed===true,extraIdx=(o.extra||[]).findIndex(f=>f.part===p[0]),approved=extraIdx>=0&&S.approvals[S.activeOrder+"_"+extraIdx]==="yes";return `<div class="partCard" onclick="inspectPart(${i})"><b>${p[0]}</b>${isTarget?`<span class="tag" style="float:right">ОСНОВНАЯ</span>`:approved?`<span class="tag greenTag" style="float:right">СОГЛАСОВАНО</span>`:""}<div class="wear ${wear<45?"bad":wear<70?"mid":"good"}">Ресурс ${wear}%</div><div class="muted">Нажми для осмотра</div></div>`}).join("")}</div></div>`}
function runTest(i){const o=activeOrder();if(!o)return;const z=S.zone,t=TESTS[z]?.[i];if(!t)return;const cost=Math.max(1,Math.round(t[1]*diagDiscount()));if(S.money<cost)return alert("Не хватает денег.");addMoney(-cost);const key=S.activeOrder+"_"+z;S.checked[key]=S.checked[key]||[];if(!S.checked[key].includes(i))S.checked[key].push(i);let found=[];const targets=TEST_TARGETS[z]?.[i]||[];if(z===o.system&&targets.includes(o.target))found.push({type:"main",text:`Основная неисправность подтверждена: ${o.target}`});(o.extra||[]).forEach(f=>{if(f.needTest===i&&z===o.system&&targets.includes(f.part)&&!(S.findings[String(S.activeOrder)]||[]).some(x=>x.part===f.part)){S.findings[String(S.activeOrder)]=[...(S.findings[String(S.activeOrder)]||[]),f];found.push({type:"extra",text:`Дополнительно обнаружено: ${f.title}`});}});modal(found.length?`<h2>🔎 Результат проверки</h2>${found.map(x=>`<p class="${x.type==="extra"?"miniGood":""}"><b>${x.text}</b></p>`).join("")}<p class="muted">Дополнительный ремонт выполняется только после согласования клиента.</p><button class="btn gold" onclick="closeModal();render()">Продолжить</button>`:`<h2>Проверка завершена</h2><p>«${t[0]}» не подтвердила новую неисправность.</p><p class="muted">Стоимость диагностики списана.</p><button class="btn dark" onclick="closeModal();render()">Продолжить</button>`);save()}
function clientType(o){if(o.clientType)return o.clientType;const types=[["Экономный",.38,"Сейчас хочу только обязательный ремонт."],["Обычный",.62,"Если действительно нужно — делайте."],["Заботливый",.78,"Лучше устранить проблему сразу."],["Скептик",.48,"Объясните, насколько это срочно."],["Торопливый",.52,"Главное — забрать машину сегодня."],["Перфекционист",.9,"Сделайте всё, чтобы машина была в порядке."]];const t=types[Math.floor(Math.random()*types.length)];o.clientType={name:t[0],chance:t[1],quote:t[2]};return o.clientType}
function offerFinding(idx){const o=activeOrder(),f=(S.findings[String(S.activeOrder)]||[])[idx];if(!o||!f)return;const ct=clientType(o),chance=Math.max(.1,Math.min(.95,ct.chance+(o.urgent?.03:0)));const yes=Math.random()<chance;S.approvals[S.activeOrder+"_"+idx]=yes?"yes":"no";if(yes){S.rep=Math.min(100,S.rep+1);modal(`<h2>✅ Клиент согласовал</h2><p>Клиент (${ct.name}): «${ct.quote}»</p><div class="notice">В заказ добавлено: <b>${f.title}</b><br>Доплата: <b>${fmt(f.partCost+f.labor)} ₽</b></div><button class="btn green" onclick="closeModal();render()">Продолжить</button>`)}else{S.rep=Math.max(0,S.rep-1);modal(`<h2>❌ Клиент отказался</h2><p>Клиент (${ct.name}): «Оставьте только первоначальный заказ.»</p><div class="notice">Дополнительная работа не выполняется.</div><button class="btn dark" onclick="closeModal();render()">Продолжить</button>`)}save()}
function inspectPart(i){const o=activeOrder(),p=SYSTEMS[S.zone].parts[i],wear=partWear(p[0],p[2]),stock=S.inventory[p[0]]||0,isMain=o&&o.target===p[0]&&S.diagnostics?.[String(S.activeOrder)]?.confirmed===true,extraIdx=o?.extra?.findIndex(f=>f.part===p[0])??-1,approved=extraIdx>=0&&S.approvals[S.activeOrder+"_"+extraIdx]==="yes";let action="";if((isMain||approved)&&wear<70)action=stock>0?`<button class="btn gold" onclick="startRepair('${p[0]}')">Снять и заменить</button>`:`<button class="btn gold" onclick="buyAndStartRepair('${p[0]}')">Купить за ${fmt(p[1])} ₽</button>`;modal(`<h2>${p[0]}</h2><div class="kpi ${wear<45?"bad":wear<70?"mid":"good"}">${wear}% ресурса</div><div class="bar"><i style="width:${wear}%"></i></div><p>${isMain?"🎯 Основная неисправность.":approved?"✅ Дополнительная работа согласована клиентом.":"🔎 Осмотрена, но ремонт пока не согласован."}</p><p class="muted">На складе: x${stock}</p>${action||`<p class="muted">Для дополнительной неисправности сначала нужно получить согласование клиента.</p>`}<button class="btn dark" onclick="closeModal()">Закрыть</button>`)}
function findPart(name){for(const z of Object.values(SYSTEMS)){const p=z.parts.find(x=>x[0]===name);if(p)return p}return null}
function warehouseTotal(){return Object.values(S.inventory).reduce((a,b)=>a+Number(b||0),0)}
function buyAndStartRepair(name){const p=findPart(name);if(!p)return;if(warehouseTotal()>=warehouseCap())return alert("Склад переполнен.");if(S.money<p[1])return alert("Не хватает денег.");addMoney(-p[1]);S.inventory[name]=(S.inventory[name]||0)+1;save();startRepair(name)}
function repairStep(){const r=S.repair,steps=["Подготовить инструмент","Снять крепление","Снять деталь","Установить новую","Проверить работу"];if(!r?.part||r.step<1||r.step>5)return;modal(`<h2>🔧 ${r.part}</h2><div class="stepper">${steps.map((x,i)=>`<div class="step ${i+1<r.step?"done":i+1===r.step?"active":""}">${i+1}. ${x}</div>`).join("")}</div><p>Текущий этап: <b>${steps[r.step-1]}</b></p><div class="notice">Этап сохраняется автоматически.</div><button class="btn gold" onclick="nextRepair()">Выполнить этап</button>`)}
function startRepair(name){const o=activeOrder(),p=findPart(name);if(!o||!p)return;let taskType="main";if(o.target===name&&S.diagnostics?.[String(S.activeOrder)]?.confirmed!==true)return alert("Сначала подтверди основную неисправность в центре диагностики.");if(o.target!==name){const idx=(o.extra||[]).findIndex(f=>f.part===name);if(idx<0||S.approvals[S.activeOrder+"_"+idx]!=="yes")return alert("Клиент не согласовал эту дополнительную работу.");taskType="extra"}if((S.inventory[name]||0)<=0)return alert("Этой детали нет на складе.");S.repair={step:1,part:name,taskType};save();closeModal();repairStep()}
function completeOrderIfReady(){const o=activeOrder();if(!o)return false;const key=String(S.activeOrder),done=S.completed[key]||{};if(done.main!==true)return false;const approved=(o.extra||[]).map((f,i)=>S.approvals[S.activeOrder+"_"+i]==="yes"?i:null).filter(i=>i!==null);if(!approved.every(i=>done["extra"+i]===true))return false;if(!S.testDrives[key])return false;const extraTotal=approved.reduce((sum,i)=>sum+o.extra[i].partCost+o.extra[i].labor,0);const total=o.pay+extraTotal+staffBonus();addMoney(total);S.rep=Math.min(100,S.rep+2);const vh=vehicleHistory(o);vh.visits++;vh.notes.unshift(`День ${S.day}: ${o.symptom} — выполнено, сумма ${fmt(total)} ₽`);vh.notes=vh.notes.slice(0,8);S.history.unshift(`${o.client}: заказ завершён на ${fmt(total)} ₽`);S.orders.splice(S.activeOrder,1);S.activeOrder=Math.max(0,Math.min(S.activeOrder,S.orders.length-1));S.checked={};S.findings={};S.approvals={};S.completed={};S.testDrives={};S.repair={step:0,part:null,taskType:"main"};save();alert(`Заказ завершён. Клиент оплатил ${fmt(total)} ₽.`);tab("orders");return true}
function nextRepair(){const r=S.repair;if(!r?.part)return;if(r.step<5){r.step++;save();repairStep();return}const o=activeOrder();if(!o)return;const allowed=o.target===r.part||((o.extra||[]).some((f,i)=>f.part===r.part&&S.approvals[S.activeOrder+"_"+i]==="yes"));if(!allowed)return alert("Эта работа не согласована.");if((S.inventory[r.part]||0)<=0)return alert("Не хватает детали на складе.");S.inventory[r.part]--;S.repairedParts=S.repairedParts||{};S.repairedParts[r.part]=100;const key=String(S.activeOrder);S.completed[key]=S.completed[key]||{};if(r.taskType==="main"){S.completed[key].main=true;addXP(55);S.history.unshift(`${o.client}: ${r.part} заменена — основная работа завершена`)}else{const idx=(o.extra||[]).findIndex(f=>f.part===r.part);if(idx>=0)S.completed[key]["extra"+idx]=true;addXP(35);S.history.unshift(`${o.client}: ${r.part} заменена — дополнительная работа выполнена`)}S.repair={step:0,part:null,taskType:"main"};closeModal();save();render();if(r.taskType==="extra")alert("Дополнительная работа выполнена. Проверь остальные согласованные работы.");else alert("Основная работа выполнена. Теперь проверь согласованные дополнительные работы и сделай тест-драйв.")}
function testDrive(){const o=activeOrder();if(!o)return;const key=String(S.activeOrder),done=S.completed[key]||{};if(done.main!==true)return alert("Сначала заверши основную работу.");const approved=(o.extra||[]).map((f,i)=>S.approvals[S.activeOrder+"_"+i]==="yes"?i:null).filter(i=>i!==null);if(!approved.every(i=>done["extra"+i]===true))return alert("Сначала выполни все согласованные дополнительные работы.");if(S.testDrives[key])return alert("Тест-драйв уже выполнен.");const outcomes={engine:["Двигатель работает ровно, посторонних симптомов не обнаружено.","После ремонта параметры двигателя стабильны."],brakes:["Торможение ровное, биение не ощущается.","Педаль тормоза работает штатно, торможение стабильное."],suspension:["Стук на неровностях исчез, автомобиль идёт ровно.","Подвеска работает без посторонних шумов."],electrical:["Запуск уверенный, напряжение зарядки стабильное.","Электрика работает штатно, повторных симптомов нет."],body:["Проверка кузова завершена, устранённая проблема больше не проявляется.","После ремонта визуальных и функциональных проблем не обнаружено."]};const arr=outcomes[o.system]||outcomes.engine;const result=arr[Math.floor(Math.random()*arr.length)];S.testDrives[key]=true;addXP(40);S.rep=Math.min(100,S.rep+1);const vh=vehicleHistory(o);vh.notes.unshift(`День ${S.day}: тест-драйв — ${result}`);vh.notes=vh.notes.slice(0,8);save();modal(`<h2>🚗 Тест-драйв завершён</h2><div class="notice">${result}</div><p>Автомобиль можно передавать клиенту.</p><button class="btn green" onclick="closeModal();render();completeOrderIfReady()">Завершить заказ</button>`)}
function renderAuction(){document.getElementById("tab-auction").innerHTML=`<div class="hero"><div><h1>Аукцион</h1><div class="muted">Новая петля: купить → восстановить → продать дороже.</div></div></div><div class="grid">${S.auction.map((a,i)=>`<div class="card"><div class="carArt"><img src="${a.img}"></div><span class="tag">Состояние ${a.condition}%</span><h3>${a.name}</h3><div class="price">${fmt(a.price)} ₽</div><div class="statrow"><span>После восстановления</span><b class="moneyPlus">${fmt(a.offer)} ₽</b></div><button class="btn gold" onclick="buyAuction(${i})">Купить</button></div>`).join("")||`<div class="notice">Лотов нет. Новые машины появятся позже.</div>`}</div><h2 style="margin-top:20px">Мои автомобили</h2><div class="grid">${S.ownedCars.map((a,i)=>`<div class="card"><div class="carArt"><img src="${a.img}"></div><h3>${a.name}</h3><div class="statrow"><span>Состояние</span><b>${a.condition}%</b></div>${a.restored?`<button class="btn green" onclick="sellAuction(${i})">Продать за ${fmt(a.offer)} ₽</button>`:`<button class="btn gold" onclick="restoreAuction(${i})">Восстановить за ${fmt(a.restoreCost)} ₽</button>`}</div>`).join("")||`<div class="muted">Пока пусто.</div>`}</div>`}
function buyAuction(i){const a=S.auction[i];if(!a)return;if(S.money<a.price)return alert("Не хватает денег.");addMoney(-a.price);S.auction.splice(i,1);const car={...a,restoreCost:Math.round((100-a.condition)*120),restored:false};S.ownedCars.push(car);S.history.unshift(`Аукцион: куплен ${a.name}`);save();modal(`<h2>${a.name}</h2><p>Машина добавлена в личный гараж.</p><p>Восстановление: <b>${fmt(car.restoreCost)} ₽</b>.</p><button class="btn gold" onclick="closeModal()">Продолжить</button>`)}
function restoreAuction(i){const a=S.ownedCars[i];if(!a||a.restored)return;if(S.money<a.restoreCost)return alert("Не хватает денег.");addMoney(-a.restoreCost);a.restored=true;a.condition=100;S.history.unshift(`Восстановлен ${a.name}`);save()}
function sellAuction(i){const a=S.ownedCars[i];if(!a||!a.restored)return alert("Сначала восстанови автомобиль.");addMoney(a.offer);S.history.unshift(`Продан ${a.name} за ${fmt(a.offer)} ₽`);S.ownedCars.splice(i,1);save()}
function renderParts(){document.getElementById("tab-parts").innerHTML=`<div class="hero"><div><h1>Запчасти</h1><div class="muted">Склад: ${Object.values(S.inventory).reduce((a,b)=>a+b,0)}/${warehouseCap()} мест.</div></div></div><div class="card">${Object.entries(SYSTEMS).flatMap(([k,z])=>z.parts).map(p=>`<div class="row"><b>${p[0]}</b><span>x${S.inventory[p[0]]||0}</span><button class="btn dark" onclick="buyPart('${p[0]}',${p[1]})">${fmt(p[1])} ₽</button></div>`).join("")}</div>`}
function buyPart(name,cost){const total=Object.values(S.inventory).reduce((a,b)=>a+b,0);if(total>=warehouseCap())return alert("Склад переполнен.");if(S.money<cost)return alert("Недостаточно денег.");addMoney(-cost);S.inventory[name]=(S.inventory[name]||0)+1;save()}
function renderStaff(){const w=[["Ученик",3000,150],["Механик",6500,300],["Диагност",9000,450],["Мастер",14000,700]];document.getElementById("tab-staff").innerHTML=`<div class="hero"><div><h1>Персонал</h1><div class="muted">Сотрудники теперь реально влияют на экономику.</div></div></div><div class="notice">Сотрудников: <b>${S.staff.length}</b> • зарплата: <b>${fmt(staffSalary())} ₽/день</b> • бонус: <b>+${staffBonus()} ₽/заказ</b></div><div class="grid">${w.map(x=>`<div class="card"><h2>${x[0]}</h2><p class="muted">Бонус +${x[2]} ₽ к выполненному заказу.</p><div class="price">${fmt(x[1])} ₽/день</div><button class="btn dark" onclick="hire(${x[1]},'${x[0]}',${x[2]})">Нанять</button></div>`).join("")}</div><div class="card" style="margin-top:14px"><h2>Команда</h2>${S.staff.map((x,i)=>`<div class="row"><span>${i+1}. ${x.name}</span><b>${fmt(x.salary)} ₽</b><span>+${x.bonus} ₽</span></div>`).join("")||`<div class="muted">Команда пока пустая.</div>`}</div>`}
function hire(cost,name,bonus){if(S.staff.length>=S.garage.lift*2)return alert("Не хватает подъёмников для такого штата.");if(S.money<cost)return alert("Не хватает денег.");addMoney(-cost);S.staff.push({name,salary:cost,bonus});S.history.unshift(`Нанят сотрудник: ${name}`);save()}
function renderUpgrade(){const u=[["lift","Подъёмники",12000],["tools","Проф. инструмент",9000],["warehouse","Большой склад",7000],["customer","Зона ожидания",6500],["diagnostic","Диагностическое оборудование",11000]];document.getElementById("tab-upgrade").innerHTML=`<div class="hero"><div><h1>Мастерская</h1><div class="muted">Каждое улучшение теперь имеет игровой эффект.</div></div></div><div class="grid">${u.map(x=>{const lvl=S.garage[x[0]];let effect=x[0]==="warehouse"?`Склад ${warehouseCap()} мест`:x[0]==="diagnostic"?`Диагностика -${Math.round((1-diagDiscount())*100)}%`:x[0]==="customer"?`Поток +${S.garage.customer*300} ₽/день`:x[0]==="tools"?`Ремонт: быстрее`:x[0]==="lift"?`До ${lvl*2} сотрудников`:"";return `<div class="card"><h2>${x[1]}</h2><div class="muted">Уровень ${lvl}/3</div><div class="notice">${effect}</div><div class="price">${fmt(x[2])} ₽</div><button class="btn gold" ${lvl>=3?"disabled":""} onclick="upgrade('${x[0]}',${x[2]})">${lvl>=3?"Максимум":"Улучшить"}</button></div>`}).join("")}</div>`}
function upgrade(k,c){if(S.garage[k]>=3)return;if(S.money<c)return alert("Не хватает денег.");addMoney(-c);S.garage[k]++;addXP(60);S.history.unshift(`Улучшение: ${k} → уровень ${S.garage[k]}`);save()}
function renderFinance(){const inc=S.ledger.filter(x=>x.value>0).reduce((a,x)=>a+x.value,0),exp=S.ledger.filter(x=>x.value<0).reduce((a,x)=>a+x.value,0);document.getElementById("tab-finance").innerHTML=`<div class="hero"><div><h1>Финансы</h1><div class="muted">Доходы, расходы и экономика мастерской.</div></div></div><div class="grid"><div class="card"><div class="muted">Доходы</div><div class="kpi moneyPlus">${fmt(inc)} ₽</div></div><div class="card"><div class="muted">Расходы</div><div class="kpi moneyMinus">${fmt(Math.abs(exp))} ₽</div></div><div class="card"><div class="muted">Баланс</div><div class="kpi">${fmt(S.money)} ₽</div></div></div><div class="card" style="margin-top:14px"><h2>Операции</h2>${S.ledger.slice(0,15).map(x=>`<div class="row"><span>День ${x.day}</span><b class="${x.value>=0?"moneyPlus":"moneyMinus"}">${x.value>=0?"+":""}${fmt(x.value)} ₽</b><span>${x.value>=0?"доход":"расход"}</span></div>`).join("")||`<div class="muted">Пока нет операций.</div>`}</div>`}
function renderProfile(){document.getElementById("tab-profile").innerHTML=`<div class="hero"><div><h1>Профиль <span class="badge">${VERSION}</span></h1><div class="muted">Прогресс сохраняется автоматически.</div></div></div><div class="grid"><div class="card"><div class="muted">Уровень</div><div class="kpi">${S.level}</div><div class="bar"><i style="width:${Math.min(100,S.xp/(S.level*100)*100)}%"></i></div><p>${S.xp}/${S.level*100} XP</p></div><div class="card"><div class="muted">Репутация</div><div class="kpi">${S.rep}/100</div><div class="bar"><i style="width:${S.rep}%"></i></div></div><div class="card"><div class="muted">Авто на восстановлении</div><div class="kpi">${S.ownedCars.length}</div></div></div><div class="card" style="margin-top:14px"><h2>Что нового в V12</h2><div class="row"><span>Диагностика привязана к реальным целям заказа</span><b>✓</b></div><div class="row"><span>Нельзя закрыть заказ заменой случайной детали</span><b>✓</b></div><div class="row"><span>Персонал даёт бонус к прибыли и имеет зарплату</span><b>✓</b></div><div class="row"><span>Аукцион: купить → восстановить → продать</span><b>✓</b></div><div class="row"><span>Улучшения мастерской дают эффекты</span><b>✓</b></div><div class="row"><span>Тест-драйв перед выдачей автомобиля</span><b>✓</b></div><div class="row"><span>История обслуживания каждого автомобиля</span><b>✓</b></div><div class="row"><span>Скрытые неисправности предлагаются клиенту отдельно</span><b>✓</b></div></div><button class="btn red" style="margin-top:14px" onclick="resetGame()">Сбросить прогресс</button>`}
function newDay(){S.day++;const revenue=Math.round(500+S.rep*12+S.level*180+S.garage.customer*300),salary=staffSalary(),maintenance=S.garage.lift*180;const branchRevenue=(S.network?.branches||[]).filter(b=>b.open).reduce((sum,b)=>sum+Math.round(700*b.level+b.capacity*260+S.rep*4),0);if(branchRevenue){addMoney(branchRevenue);(S.network.branches||[]).forEach(b=>{if(b.open)b.revenue=(b.revenue||0)+Math.round(700*b.level+b.capacity*260+S.rep*4)});S.history.unshift(`Сеть: филиалы принесли +${fmt(branchRevenue)} ₽`)}addMoney(revenue-salary-maintenance);const maxOrders=Math.min(6,2+S.level);const existing=new Set(S.orders.map(o=>o.client+"|"+o.symptom));const pool=structuredClone(ORDER_POOL).filter(o=>!existing.has(o.client+"|"+o.symptom));S.orders.push(...pool.slice(0,Math.max(0,maxOrders-S.orders.length)));S.activeOrder=Math.min(S.activeOrder,Math.max(0,S.orders.length-1));S.history.unshift(`День ${S.day}: поток +${fmt(revenue)} ₽, зарплаты/обслуживание -${fmt(salary+maintenance)} ₽`);save();alert(`День ${S.day} начался.`)}
function resetGame(){if(confirm("Сбросить весь прогресс?")){S=structuredClone(DEFAULT);save()}}
/* V16 startup moved to end */
function branchCost(level){return [0,95000,180000,350000][level]||999999}
function branchOpenCost(){return 180000+S.network.branches.length*90000}
function upgradeBranch(i){const b=S.network.branches[i];if(!b)return;if(b.level>=3)return alert("Филиал уже максимального уровня.");const cost=branchCost(b.level+1);if(S.money<cost)return alert("Не хватает денег.");addMoney(-cost);b.level++;b.capacity=Math.min(6,b.capacity+1);S.network.reputation=Math.min(100,S.network.reputation+2);S.history.unshift(`${b.name}: уровень повышен до ${b.level}`);save()}
function openBranch(){if(S.network.branches.length>=4)return alert("Максимум 4 филиала в V13.");const cost=branchOpenCost();if(S.money<cost)return alert("Не хватает денег на открытие филиала.");addMoney(-cost);const n=S.network.branches.length+1;S.network.branches.push({name:`Филиал №${n}`,city:["Север","Юг","Запад"][n-2]||"Район",level:1,capacity:2,revenue:0,staff:[],open:true});S.history.unshift(`Открыт новый филиал №${n}`);save();modal(`<h2>🏢 Филиал открыт</h2><p>Теперь у сети ${S.network.branches.length} мастерских.</p><button class="btn gold" onclick="closeModal()">Продолжить</button>`)}
function toggleBranch(i){const b=S.network.branches[i];if(!b)return;if(i===0)return alert("Главную мастерскую нельзя закрыть.");b.open=!b.open;S.history.unshift(`${b.name}: ${b.open?"открыт":"закрыт"}`);save()}
function renderNetwork(){const bs=S.network?.branches||[];document.getElementById("tab-network").innerHTML=`<div class="hero"><div><h1>🏢 Сеть автосервисов <span class="badge">V13</span></h1><div class="muted">Открывай филиалы, повышай их уровень и получай дополнительную прибыль каждый новый день.</div></div><button class="btn gold" onclick="openBranch()">Открыть филиал — ${fmt(branchOpenCost())} ₽</button></div><div class="notice"><b>Рейтинг сети:</b> ${S.network.reputation}/100 • <b>Филиалов:</b> ${bs.length}/4 • <b>Доход филиалов за день:</b> ${fmt(bs.filter(b=>b.open).reduce((sum,b)=>sum+Math.round(700*b.level+b.capacity*260+S.rep*4),0))} ₽</div><div class="grid">${bs.map((b,i)=>{const daily=Math.round(700*b.level+b.capacity*260+S.rep*4);const up=branchCost(b.level+1);return `<div class="card"><span class="tag">${b.open?"ОТКРЫТ":"ЗАКРЫТ"}</span><h2>${b.name}</h2><p class="muted">📍 ${b.city}</p><div class="statrow"><span>Уровень</span><b>${b.level}/3</b></div><div class="statrow"><span>Мощность</span><b>${b.capacity} поста</b></div><div class="statrow"><span>Доход/день</span><b class="moneyPlus">+${fmt(daily)} ₽</b></div><div class="statrow"><span>Накоплено</span><b>${fmt(b.revenue||0)} ₽</b></div><div class="actions"><button class="btn gold" ${b.level>=3?"disabled":""} onclick="upgradeBranch(${i})">${b.level>=3?"Максимум":"Улучшить • "+fmt(up)+" ₽"}</button>${i?`<button class="btn dark" onclick="toggleBranch(${i})">${b.open?"Закрыть":"Открыть"}</button>`:""}</div></div>`}).join("")}</div><div class="card" style="margin-top:14px"><h2>📈 Как работает сеть</h2><div class="row"><span>Каждый новый день открытые филиалы приносят прибыль</span><b>✓</b></div><div class="row"><span>Уровень филиала увеличивает доход и вместимость</span><b>✓</b></div><div class="row"><span>В V16 можно будет распределять персонал по филиалам</span><b>→</b></div><div class="row"><span>В V16 появятся конкурирующие СТО и локальный рейтинг</span><b>→</b></div></div>`}
function renderShop(){const vip=isVip();document.getElementById("tab-shop").innerHTML=`<div class="hero"><div><h1>Премиум-магазин <span class="badge">V12</span></h1><div class="muted">Монетизация подготовлена: товары, премиум-валюта и VIP. В VK Mini App покупка передаётся через VK Bridge.</div></div><div class="notice">💎 <b>${fmt(S.premium)}</b> ${vip?`• ⭐ VIP до ${new Date(S.vipUntil).toLocaleDateString("ru-RU")}`:""}</div></div><div class="grid">${Object.entries(PREMIUM_PRODUCTS).map(([id,p])=>`<div class="card"><span class="tag">${id==="vip"?"VIP":"ПАКЕТ"}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="kpi">💎 ${fmt(p.stars)}</div><div class="price">${p.price}</div><button class="btn gold" onclick="startPayment('${id}')">Купить</button></div>`).join("")}</div><div class="card" style="margin-top:14px"><h2>Покупки за 💎</h2><div class="row"><span>Дополнительный слот заказа</span><button class="btn dark" onclick="spendPremium(100,()=>{S.extraSlots=(S.extraSlots||0)+1;S.history.unshift('Куплен дополнительный слот заказа')})">100 💎</button></div><div class="row"><span>Ускоритель ремонта на день</span><button class="btn dark" onclick="spendPremium(150,()=>{S.repairBoostUntil=Date.now()+86400000;S.history.unshift('Куплен ускоритель ремонта')})">150 💎</button></div><div class="row"><span>Премиальный набор запчастей</span><button class="btn dark" onclick="spendPremium(250,()=>{['Моторное масло','Свеча зажигания','Передние колодки','Стойка стабилизатора'].forEach(n=>S.inventory[n]=(S.inventory[n]||0)+1);S.history.unshift('Куплен премиальный набор запчастей')})">250 💎</button></div></div><div class="notice" style="margin-top:14px"><b>Важно:</b> для настоящих платежей в опубликованной VK Mini App нужны настроенные товары и серверная проверка успешной покупки. В веб-превью платёжные данные не используются.</div>`}



/* ==================== V16: ЦЕНТР ДИАГНОСТИКИ ==================== */
const DIAG_METHODS={
 visual:{name:"Визуальный осмотр",icon:"🔎",img:"images/bmw_5_g30.png",cost:500,time:15,systems:"all",desc:"Проверка состояния узлов и агрегатов, поиск явных дефектов.",clue:"Внешние повреждения, подтёки жидкостей, износ деталей, ремни и шланги."},
 scanner:{name:"OBD-диагностика",icon:"📟",img:"images/scanner_realistic.png",cost:800,time:20,systems:["engine","electrical"],desc:"Считывание ошибок и параметров электронных систем.",clue:"Коды ошибок, пропуски зажигания, датчики, смесь и напряжение."},
 lift:{name:"Проверка на подъёмнике",icon:"🏗️",img:"images/lift_realistic.png",cost:1200,time:25,systems:["suspension","brakes","body"],desc:"Осмотр подвески, днища, течей и состояния узлов.",clue:"Люфты, крепления, течи, повреждения и износ деталей."},
 play:{name:"Проверка люфтов",icon:"🛠️",img:"images/parts_realistic.png",cost:1000,time:20,systems:["suspension","steering","brakes"],desc:"Проверка рулевого управления, подвески и ходовой части.",clue:"Люфт шаровых, рулевых соединений, ступиц и элементов ходовой."},
 brakes:{name:"Проверка тормозов",icon:"🛞",img:"images/brake_realistic.png",cost:1000,time:20,systems:["brakes"],desc:"Оценка состояния тормозной системы и износа колодок.",clue:"Толщина колодок, состояние дисков, шлангов и тормозных контуров."},
 measure:{name:"Измерения",icon:"📐",img:"images/scanner_realistic.png",cost:800,time:15,systems:["engine","brakes","electrical","body"],desc:"Проверка давления, напряжения, температуры и других параметров.",clue:"Точные значения вместо догадок: напряжение, давление, температура, толщина."},
 compression:{name:"Замер компрессии",icon:"⏱️",img:"images/compressor_realistic.png",cost:1500,time:25,systems:["engine"],desc:"Проверка компрессии в цилиндрах двигателя.",clue:"Равномерность компрессии и состояние цилиндров двигателя."},
 road:{name:"Тест-драйв",icon:"🚗",img:"images/bmw_5_g30.png",cost:1500,time:30,systems:["engine","brakes","suspension","electrical"],desc:"Проверка поведения автомобиля на дороге.",clue:"Шумы, вибрации, запуск, поведение под нагрузкой и работа систем."}
};
function ensureDiagnostics(){S.diagnostics=S.diagnostics||{};const k=String(S.activeOrder);S.diagnostics[k]=S.diagnostics[k]||{tests:[],confirmed:false,confidence:0,clues:[],selected:"visual"};const d=S.diagnostics[k];if(!Array.isArray(d.tests))d.tests=[];if(!Array.isArray(d.clues))d.clues=[];if(!d.selected||!DIAG_METHODS[d.selected])d.selected="visual";return d}
function diagCanUse(m){const o=activeOrder(),systems=DIAG_METHODS[m]?.systems;if(!o)return false;return systems==="all"||Array.isArray(systems)&&systems.includes(o.system)}
function selectDiagnostic(id){const d=ensureDiagnostics();if(!DIAG_METHODS[id])return;d.selected=id;save();renderDiagnostics()}
function diagnosticOutcome(method){const o=activeOrder();if(!o)return null;const m=DIAG_METHODS[method];if(!m||!diagCanUse(method))return null;const d=ensureDiagnostics();const z=o.system;let main=false;
 if(method!=="visual"){
   main=(TEST_TARGETS[z]?.[o.test]||[]).includes(o.target)||
     (method==="scanner"&&["engine","electrical"].includes(z))||
     (method==="lift"&&["suspension","brakes"].includes(z))||
     (method==="play"&&z==="suspension")||
     (method==="brakes"&&z==="brakes")||
     (method==="measure")||
     (method==="compression"&&z==="engine")||
     (method==="road"&&["engine","brakes","suspension","electrical"].includes(z));
 }
 let extra=(o.extra||[]).filter(f=>f.needTest===o.test&&f.needTest>=0&&z===o.system);
 if(method==="visual"||method==="lift"||method==="measure"||method==="play"||method==="brakes")extra=(o.extra||[]).filter(f=>z===o.system);
 return {main,extra};
}
function runDiagnostic(method){const o=activeOrder();const m=DIAG_METHODS[method];if(!o||!m)return;if(!diagCanUse(method))return alert(`Метод «${m.name}» сейчас не подходит для автомобиля.`);const d=ensureDiagnostics();if(d.tests.includes(method))return alert("Эта проверка уже выполнена для текущего заказа.");const cost=Math.max(0,Math.round(m.cost*diagDiscount()));if(S.money<cost)return alert("Не хватает денег на диагностику.");addMoney(-cost);d.tests.push(method);let outcome=diagnosticOutcome(method),found=[];if(outcome?.main){d.confirmed=true;d.confidence=Math.min(100,d.confidence+42);d.clues.push(`${m.name}: подтверждена проблема — ${o.target}.`);found.push(`<p class="miniGood"><b>🎯 Основная неисправность подтверждена.</b><br>${o.target}</p>`)}else{d.confidence=Math.min(100,d.confidence+12);d.clues.push(`${m.name}: получены диагностические данные без окончательного подтверждения.`)}(outcome?.extra||[]).forEach(f=>{const already=(S.findings[String(S.activeOrder)]||[]).some(x=>x.part===f.part);if(!already){S.findings[String(S.activeOrder)]=[...(S.findings[String(S.activeOrder)]||[]),f];found.push(`<p class="miniGood"><b>🔎 Дополнительно найдено:</b> ${f.title}</p>`)}});S.history.unshift(`${o.client}: ${m.name} — ${cost?fmt(cost)+" ₽":"бесплатно"}`);save();modal(`<h2>${m.icon} ${m.name}</h2><div class="notice">Время: <b>${m.time} мин</b><br>Зона: <b>${SYSTEMS[o.system].name}</b></div>${found.join("")||`<p>${m.clue}</p><p class="muted">Проверка сузила круг причин, но окончательный диагноз пока не подтверждён.</p>`}<button class="btn gold" onclick="closeModal();renderDiagnostics();renderRepair()">Продолжить</button>`)}
function confirmDiagnosis(){const o=activeOrder(),d=ensureDiagnostics();if(!o)return;if(!d.confirmed)return alert("Сначала проведи проверку, которая подтверждает основную неисправность.");d.confirmed=true;d.confidence=Math.max(75,d.confidence);S.history.unshift(`${o.client}: диагноз подтверждён — ${o.target}`);save();modal(`<h2>✅ Диагноз подтверждён</h2><div class="notice"><b>${o.target}</b><br>Теперь можно переходить к ремонту.</div><button class="btn green" onclick="closeModal();tab('repair')">Перейти к ремонту</button>`)}
function renderDiagnostics(){const el=document.getElementById("tab-diagnostics");if(!el)return;const o=activeOrder();if(!o){el.innerHTML=`<div class="diagEmpty"><h1>🔎 Центр диагностики <span class="badge">V16</span></h1><div class="notice">Нет активного заказа. Сначала возьми автомобиль в работу.</div></div>`;return}const d=ensureDiagnostics(),methods=Object.entries(DIAG_METHODS),selected=DIAG_METHODS[d.selected]||DIAG_METHODS.visual,usedCount=d.tests.length;
 const methodCards=methods.map(([id,m])=>{const used=d.tests.includes(id),available=diagCanUse(id),selectedCls=id===d.selected?"diagSelected":"";return `<article class="diagMethodCard ${selectedCls} ${used?"diagUsed":""} ${available?"":"diagDisabled"}" onclick="selectDiagnostic('${id}')"><div class="diagImage"><img src="${m.img}" alt="${m.name}"></div><div class="diagCardBody"><div class="diagCardTitle"><h3>${m.name}</h3>${used?'<span class="diagCheck">✓</span>':''}</div><p>${m.desc}</p><div class="diagMeta"><span>◷ ${m.time} мин</span><b>${fmt(Math.round(m.cost*diagDiscount()))} ₽</b></div></div></article>`}).join("");
 const checks=selected===DIAG_METHODS.visual?"Внешние повреждения|Подтёки жидкостей|Состояние ремней и шлангов|Крепления и соединения|Общие признаки неисправностей":selected.clue;
 el.innerHTML=`<div class="diagPage"><div class="diagMain"><div class="diagHeading"><div><h1>🔎 Центр диагностики</h1><p>Выберите метод диагностики, чтобы найти неисправности автомобиля.</p></div><div class="diagScore"><b>${d.confidence}%</b><span>уверенность</span></div></div><div class="diagGridNew">${methodCards}</div><div class="diagHint"><span>ℹ</span><div><b>Выбор диагностики</b><small>Нажмите на нужный метод, чтобы увидеть подробности справа.</small></div><strong>${usedCount}/${methods.length}</strong></div></div><aside class="diagSide"><h2>${selected.icon} ${selected.name}</h2><div class="diagSideImage"><img src="${selected.img}" alt="${selected.name}"></div><p class="diagSideDesc">${selected.desc}</p><div class="diagDivider"></div><div class="diagSideStats"><div><span>◷</span> Время: <b>${selected.time} минут</b></div><div><span>▱</span> Стоимость: <b>${fmt(Math.round(selected.cost*diagDiscount()))} ₽</b></div><div><span>◉</span> Уверенность: <b>${Math.min(95,d.confidence+(selected.id?0:0)+20)}%</b></div><div><span>⚙</span> Оборудование: <b>${selected.id==='scanner'?'OBD-сканер':selected.id==='lift'?'Подъёмник':selected.id==='compression'?'Компрессометр':'Не требуется'}</b></div></div><div class="diagDivider"></div><h3>Что проверяется:</h3><ul class="diagChecklist">${checks.split('|').map(x=>`<li>✓ ${x}</li>`).join("")}</ul><div class="diagDivider"></div><div class="diagResult"><b>Результат:</b><span>${d.tests.includes(d.selected)?(d.confirmed?`Основная неисправность: ${o.target}`:"Получены диагностические данные."):"После запуска проверки здесь появится результат."}</span></div><div class="diagInfo">Чем больше методов диагностики вы используете, тем выше точность определения неисправности. Некоторые неисправности могут быть скрыты и потребуют дополнительных проверок.</div><button class="btn green diagStart" onclick="runDiagnostic('${d.selected}')" ${!diagCanUse(d.selected)||d.tests.includes(d.selected)?"disabled":""}>🔧 ${d.tests.includes(d.selected)?"Проверка выполнена":"Начать диагностику"}</button></aside></div><div class="diagBottom"><div class="diagVehicle"><img src="${carImage(CARS[o.car][0])}" alt=""><div><b>${CARS[o.car][0]}</b><span>Пробег: ${Math.round(150000+o.car*17000).toLocaleString('ru-RU')} км</span><span>Двигатель: 1.6 • КПП: Автомат</span></div><div class="diagComplaint"><b>Задача клиента:</b><span>${o.symptom}</span></div></div><div class="card"><h3>🎯 Диагноз</h3><div class="diagnosisState ${d.confirmed?"ok":"wait"}">${d.confirmed?`<b>Подтверждено</b><span>${o.target}</span>`:`<b>Не подтверждён</b><span>Проведи необходимые проверки.</span>`}</div><button class="btn ${d.confirmed?"green":"dark"}" onclick="confirmDiagnosis()">${d.confirmed?"Перейти к ремонту":"Подтвердить диагноз"}</button></div></div>`}

/* ==================== V16: РЕАЛИСТИЧНЫЕ АССЕТЫ И ШИННЫЙ СЕРВИС ==================== */
const TIRE_JOBS=[
 {title:"Сезонная переобувка",car:"Kia Ceed JD",pay:4200,steps:["Снять колёса","Разбортовать","Установить шины","Накачать","Балансировать","Установить"],need:["tireMachine","balancer"]},
 {title:"Балансировка 4 колёс",car:"Toyota Camry XV40",pay:2600,steps:["Закрепить колесо","Запустить стенд","Считать дисбаланс","Установить грузики","Повторная проверка"],need:["balancer"]},
 {title:"Ремонт прокола",car:"Hyundai Solaris",pay:1800,steps:["Снять колесо","Разбортовать","Найти прокол","Устранить прокол","Накачать","Балансировать"],need:["tireMachine","balancer"]}
];
function ensureV15_1(){S.equipment=S.equipment||{};S.equipment.tireMachine=S.equipment.tireMachine||{level:0,uses:0};S.equipment.balancer=S.equipment.balancer||{level:0,uses:0};S.tireJob=S.tireJob||null;S.tireStats=S.tireStats||{completed:0,revenue:0};}
ensureV15_1();
function eqName(k){return k==="tireMachine"?"Шиномонтажный станок":"Балансировочный станок"}
function eqCost(k,l){const base=k==="tireMachine"?22000:18000;return base*Math.max(1,l)}
function buyOrUpgradeEquipment(k){ensureV15_1();const e=S.equipment[k];const next=e.level+1;if(next>3)return alert("Максимальный уровень оборудования.");const cost=eqCost(k,next);if(S.money<cost)return alert("Не хватает денег.");addMoney(-cost);e.level=next;S.history.unshift(`${eqName(k)}: уровень ${next}`);save();}
function equipmentReady(keys){ensureV15_1();return keys.every(k=>S.equipment[k].level>0)}
function startTireJob(i){ensureV15_1();const j=TIRE_JOBS[i];if(!j)return;if(!equipmentReady(j.need))return alert("Для этой работы сначала купи необходимое оборудование.");S.tireJob={id:i,step:0};save();}
function doTireStep(){ensureV15_1();const r=S.tireJob;if(!r)return;const j=TIRE_JOBS[r.id];if(!j)return;if(r.step<j.steps.length){r.step++;j.need.forEach(k=>S.equipment[k].uses++);if(r.step<j.steps.length){save();return}}
 addMoney(j.pay);addXP(45);S.rep=Math.min(100,S.rep+1);S.tireStats.completed++;S.tireStats.revenue+=j.pay;S.history.unshift(`Шиномонтаж: ${j.title} — +${fmt(j.pay)} ₽`);S.tireJob=null;save();modal(`<h2>🛞 Работа завершена</h2><div class="notice">${j.title}<br><b class="moneyPlus">+${fmt(j.pay)} ₽</b></div><button class="btn green" onclick="closeModal()">Готово</button>`)}
function renderTires(){ensureV15_1();const tm=S.equipment.tireMachine,ba=S.equipment.balancer,r=S.tireJob,j=r?TIRE_JOBS[r.id]:null;const station=(key,img,title,desc)=>{const e=S.equipment[key],next=e.level+1,cost=eqCost(key,next);return `<div class="card ${e.level?"":"stationLocked"}"><div class="stationArt"><img src="${img}"></div><h2>${title}</h2><div class="statrow"><span>Уровень</span><b>${e.level}/3</b></div><div class="statrow"><span>Выполнено операций</span><b>${e.uses}</b></div><p class="muted">${desc}</p><button class="btn gold" ${e.level>=3?"disabled":""} onclick="buyOrUpgradeEquipment('${key}')">${e.level?`Улучшить • ${fmt(cost)} ₽`:`Купить • ${fmt(cost)} ₽`}</button></div>`};
 document.getElementById("tab-tires").innerHTML=`<div class="hero"><div><h1>🛞 Шиномонтаж <span class="badge">V16</span></h1><div class="muted">Станки участвуют в работе: без оборудования соответствующий заказ выполнить нельзя.</div></div><span class="tag">Выручка ${fmt(S.tireStats.revenue)} ₽</span></div><div class="tireHero">${station("tireMachine","images/tire_machine_realistic.png","Шиномонтажный станок","Разбортовка, монтаж шин и ремонт проколов.")}${station("balancer","images/balancer_realistic.png","Балансировочный станок","Поиск дисбаланса, установка грузиков и контрольная проверка.")}</div>${j?`<div class="card" style="margin-top:14px"><h2>${j.title} — ${j.car}</h2><div class="tireSteps">${j.steps.map((x,i)=>`<div class="tireStep ${i<r.step?"done":i===r.step?"active":""}">${i+1}. ${x}</div>`).join("")}</div><div class="notice">Текущий этап: <b>${j.steps[Math.min(r.step,j.steps.length-1)]}</b></div><button class="btn green" onclick="doTireStep()">${r.step>=j.steps.length-1?"Завершить работу":"Выполнить этап"}</button></div>`:`<div class="card" style="margin-top:14px"><h2>Доступные работы</h2><div class="grid">${TIRE_JOBS.map((x,i)=>`<div class="card"><span class="tag">${x.car}</span><h3>${x.title}</h3><div class="price">${fmt(x.pay)} ₽</div><p class="muted">Оборудование: ${x.need.map(eqName).join(" + ")}</p><button class="btn ${equipmentReady(x.need)?"gold":"dark"}" onclick="startTireJob(${i})" ${equipmentReady(x.need)?"":"disabled"}>${equipmentReady(x.need)?"Начать работу":"Нужно оборудование"}</button></div>`).join("")}</div></div>`}`
}
function renderUpgrade(){ensureV15_1();const u=[["lift","Подъёмники",12000],["tools","Проф. инструмент",9000],["warehouse","Большой склад",7000],["customer","Зона ожидания",6500],["diagnostic","Диагностическое оборудование",11000]];document.getElementById("tab-upgrade").innerHTML=`<div class="hero"><div><h1>Мастерская <span class="badge">V16</span></h1><div class="muted">Развивай обычные посты и специальное оборудование.</div></div><button class="btn dark" onclick="tab('tires')">🛞 Открыть шиномонтаж</button></div><div class="grid">${u.map(x=>{const lvl=S.garage[x[0]];let effect=x[0]==="warehouse"?`Склад ${warehouseCap()} мест`:x[0]==="diagnostic"?`Диагностика -${Math.round((1-diagDiscount())*100)}%`:x[0]==="customer"?`Поток +${S.garage.customer*300} ₽/день`:x[0]==="tools"?`Ремонт: быстрее`:x[0]==="lift"?`До ${lvl*2} сотрудников`:"";return `<div class="card"><h2>${x[1]}</h2><div class="muted">Уровень ${lvl}/3</div><div class="notice">${effect}</div><div class="price">${fmt(x[2])} ₽</div><button class="btn gold" ${lvl>=3?"disabled":""} onclick="upgrade('${x[0]}',${x[2]})">${lvl>=3?"Максимум":"Улучшить"}</button></div>`}).join("")}</div><div class="card" style="margin-top:14px"><h2>🛞 Специальное оборудование V16</h2><div class="row"><span>Шиномонтажный станок</span><b>${S.equipment.tireMachine.level}/3</b><button class="btn dark" onclick="tab('tires')">Управлять</button></div><div class="row"><span>Балансировочный станок</span><b>${S.equipment.balancer.level}/3</b><button class="btn dark" onclick="tab('tires')">Управлять</button></div></div>`}
function render(){ensureV15_1();document.getElementById("money").textContent=fmt(S.money);document.getElementById("level").textContent=S.level;document.getElementById("rep").textContent=S.rep;document.getElementById("day").textContent=S.day;document.getElementById("badge").textContent=S.orders.length;renderGarage();renderOrders();renderRepair();renderDiagnostics();renderAuction();renderParts();renderTires();renderStaff();renderUpgrade();renderFinance();renderProfile();renderShop();renderNetwork()}

// V16 startup after all constants and overrides are initialized
document.querySelectorAll(".nav").forEach(b=>b.onclick=()=>tab(b.dataset.tab));
render();
